#include <stdio.h>

#define MAXN 100000

long long bit[MAXN + 1];
int values[MAXN + 1];

void add(int index, long long delta, int n) {
    while (index <= n) {
        bit[index] += delta;
        index += index & -index;
    }
}

long long prefix_sum(int index) {
    long long sum = 0;
    while (index > 0) {
        sum += bit[index];
        index -= index & -index;
    }
    return sum;
}

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        scanf("%d", &values[i]);
        add(i, values[i], n);
    }

    for (int i = 0; i < q; i++) {
        int type, k;
        scanf("%d %d", &type, &k);

        if (type == 0) {
            int p;
            scanf("%d", &p);
            add(k, p - values[k], n);
            values[k] = p;
        } else {
            printf("%lld\n", prefix_sum(k));
        }
    }

    return 0;
}
